CREATE   PROCEDURE [synapse_ce].[usp_Update_team]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[administratorid] = stg.[administratorid],
		tgt.[administratorid_entitytype] = stg.[administratorid_entitytype],
		tgt.[administratoridname] = stg.[administratoridname],
		tgt.[administratoridyominame] = stg.[administratoridyominame],
		tgt.[apitil_itsmteam] = stg.[apitil_itsmteam],
		tgt.[apitil_levelitsm] = stg.[apitil_levelitsm],
		tgt.[apitil_notifyonassign] = stg.[apitil_notifyonassign],
		tgt.[apitil_notifyoncreate] = stg.[apitil_notifyoncreate],
		tgt.[apitil_notifyonescalation] = stg.[apitil_notifyonescalation],
		tgt.[apitil_notifyonslastatuschange] = stg.[apitil_notifyonslastatuschange],
		tgt.[apitil_notifyonstatuschange] = stg.[apitil_notifyonstatuschange],
		tgt.[apitil_notifyonupdate] = stg.[apitil_notifyonupdate],
		tgt.[apitil_outgoingitsmemailqueue] = stg.[apitil_outgoingitsmemailqueue],
		tgt.[apitil_outgoingitsmemailqueue_entitytype] = stg.[apitil_outgoingitsmemailqueue_entitytype],
		tgt.[apitil_outgoingitsmemailqueuename] = stg.[apitil_outgoingitsmemailqueuename],
		tgt.[apuk_teammanagerid] = stg.[apuk_teammanagerid],
		tgt.[apuk_teammanagerid_entitytype] = stg.[apuk_teammanagerid_entitytype],
		tgt.[apuk_teammanageridname] = stg.[apuk_teammanageridname],
		tgt.[apuk_teammanageridyominame] = stg.[apuk_teammanageridyominame],
		tgt.[azureactivedirectoryobjectid] = stg.[azureactivedirectoryobjectid],
		tgt.[businessunitid] = stg.[businessunitid],
		tgt.[businessunitid_entitytype] = stg.[businessunitid_entitytype],
		tgt.[businessunitidname] = stg.[businessunitidname],
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		tgt.[description] = stg.[description],
		tgt.[emailaddress] = stg.[emailaddress],
		tgt.[exchangerate] = stg.[exchangerate],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[isdefault] = stg.[isdefault],
		tgt.[issastokenset] = stg.[issastokenset],
		tgt.[membershiptype] = stg.[membershiptype],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[msdynmkt_associatedevent] = stg.[msdynmkt_associatedevent],
		tgt.[msdynmkt_associatedevent_entitytype] = stg.[msdynmkt_associatedevent_entitytype],
		tgt.[msdynmkt_associatedeventname] = stg.[msdynmkt_associatedeventname],
		tgt.[name] = stg.[name],
		tgt.[organizationid] = stg.[organizationid],
		tgt.[organizationidname] = stg.[organizationidname],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[processid] = stg.[processid],
		tgt.[queueid] = stg.[queueid],
		tgt.[queueid_entitytype] = stg.[queueid_entitytype],
		tgt.[queueidname] = stg.[queueidname],
		tgt.[regardingobjectid] = stg.[regardingobjectid],
		tgt.[regardingobjectid_entitytype] = stg.[regardingobjectid_entitytype],
		tgt.[regardingobjecttypecode] = stg.[regardingobjecttypecode],
		tgt.[sastoken] = stg.[sastoken],
		tgt.[sharelinkqualifier] = stg.[sharelinkqualifier],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[stageid] = stg.[stageid],
		tgt.[systemmanaged] = stg.[systemmanaged],
		tgt.[teamid] = stg.[teamid],
		tgt.[teamtemplateid] = stg.[teamtemplateid],
		tgt.[teamtemplateid_entitytype] = stg.[teamtemplateid_entitytype],
		tgt.[teamtype] = stg.[teamtype],
		tgt.[transactioncurrencyid] = stg.[transactioncurrencyid],
		tgt.[transactioncurrencyid_entitytype] = stg.[transactioncurrencyid_entitytype],
		tgt.[transactioncurrencyidname] = stg.[transactioncurrencyidname],
		tgt.[traversedpath] = stg.[traversedpath],
		tgt.[versionnumber] = stg.[versionnumber],
		tgt.[yominame] = stg.[yominame]
	 FROM [synapse_ce].[team] tgt
		INNER JOIN [staging_ce].[team] stg
			ON tgt.[id] = stg.[id]
END
